import{_ as e,c as t,o as r,b2 as n}from"./chunks/framework.CUhoHPxN.js";const p=JSON.parse('{"title":"C7Preview（C7 附件预览）设计说明","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-08-c7-preview-design.md","filePath":"superpowers/specs/2026-05-08-c7-preview-design.md"}'),s={name:"superpowers/specs/2026-05-08-c7-preview-design.md"};function g(d,o,c,i,l,a){return r(),t("div",null,[...o[0]||(o[0]=[n('<h1 id="c7preview-c7-附件预览-设计说明" tabindex="-1">C7Preview（C7 附件预览）设计说明 <a class="header-anchor vp-link" href="#c7preview-c7-附件预览-设计说明" aria-label="Permalink to &quot;C7Preview（C7 附件预览）设计说明&quot;">​</a></h1><p><strong>日期</strong>：2026-05-08<br><strong>状态</strong>：已定稿（经 brainstorming 澄清与「设计确认」）<br><strong>依据</strong>：<code>原始需求/前端/C7预览.md</code> + Q&amp;A 结论（<strong>1B、2B、3B、4B、5B、6B</strong>）及实现路径 <strong>路径 2</strong>（<code>index.vue</code> + <code>parseUrls.ts</code> + <code>inferMediaKind.ts</code>）</p><hr><h2 id="_1-背景与目标" tabindex="-1">1. 背景与目标 <a class="header-anchor vp-link" href="#_1-背景与目标" aria-label="Permalink to &quot;1. 背景与目标&quot;">​</a></h2><ul><li><strong>背景</strong>：列表/详情常需预览 <strong>图片 / 视频 / 普通文件</strong>；附件常以 <strong>逗号分隔 URL 串</strong> 存储；触发方式需支持 <strong>直接展示封面</strong>、<strong>按钮聚合</strong>、<strong>文件表格式列表</strong>。</li><li><strong>目标</strong>：提供 <strong><code>C7Preview</code></strong>：解析 <strong><code>urls</code></strong>；按 <strong><code>autoDetect</code> / <code>displayType</code></strong> 决定每条资源类型；三种 <strong><code>coverType</code></strong> 下触发与 <strong>原始需求</strong> 一致的预览行为（多图 Element Plus 预览、视频 <strong><code>C7Dialog</code> + video</strong>、文件 <strong><code>window.open</code></strong>）；<strong><code>onPreview</code>（含异步）</strong> 可拦截；<strong><code>preview</code> / <code>close</code></strong> 事件。</li><li><strong>非目标</strong>：上传、转码、Office 在线预览；组件内发起鉴权请求；首版 <strong>不</strong> 支持 <strong><code>urls: string[]</code></strong>（仅 <strong>逗号分隔字符串</strong>，见 <strong>第 4 节</strong>）。</li></ul><hr><h2 id="_2-命名、边界与落点" tabindex="-1">2. 命名、边界与落点 <a class="header-anchor vp-link" href="#_2-命名、边界与落点" aria-label="Permalink to &quot;2. 命名、边界与落点&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>约定</th></tr></thead><tbody><tr><td><strong>对外组件名</strong></td><td><strong><code>C7Preview</code></strong></td></tr><tr><td><strong>目录</strong></td><td><strong><code>quick-ui/src/packages/C7Preview/index.vue</code></strong>，同包 <strong><code>parseUrls.ts</code></strong>、<strong><code>inferMediaKind.ts</code></strong>（纯函数，可单测）</td></tr><tr><td><strong>实现形态</strong></td><td>主 UI 与状态机在 <strong><code>index.vue</code></strong>；<strong>URL 拆分</strong>与<strong>扩展名推断</strong>不得散落在模板内联逻辑中。</td></tr><tr><td><strong>全局注册</strong></td><td>在 <strong><code>quick-ui/src/packages/index.js</code></strong> 中 <strong><code>export</code></strong> 与 <strong><code>installPackages</code></strong> 注册，与其它 C7 一致。</td></tr></tbody></table></div><p><strong>职责</strong>：解析展示 <strong><code>urls</code></strong>；按条推断或套用类型；三种 <strong><code>coverType</code></strong>；视频弹窗生命周期（含关闭时暂停与进度归零）；钩子与事件约定。</p><p><strong>不负责</strong>：保证 URL 可访问性、跨域视频首帧、浏览器对 <code>window.open</code> 的拦截策略。</p><hr><h2 id="_3-类型推断与-displaytype-1b" tabindex="-1">3. 类型推断与 <code>displayType</code>（<strong>1B</strong>） <a class="header-anchor vp-link" href="#_3-类型推断与-displaytype-1b" aria-label="Permalink to &quot;3. 类型推断与 `displayType`（**1B**）&quot;">​</a></h2><ul><li><strong><code>inferMediaKind(url: string): &#39;image&#39; \\| &#39;video&#39; \\| &#39;file&#39;</code></strong><ul><li>从 URL 取 <strong>pathname</strong>（忽略 <strong>hash</strong>；<strong>strip query 后再取扩展名</strong>，避免 <code>?x=.png</code> 误判）。</li><li><strong>image</strong>：<code>jpg</code>、<code>jpeg</code>、<code>png</code>、<code>gif</code>、<code>webp</code>、<code>bmp</code>、<code>svg</code>（扩展名 <strong>大小写不敏感</strong>）。</li><li><strong>video</strong>：<code>mp4</code>、<code>webm</code>、<code>ogg</code>、<code>mov</code>、<code>avi</code>。</li><li><strong>其余</strong>：<strong><code>file</code></strong>。</li></ul></li><li><strong><code>autoDetect === true</code>（建议默认 <code>true</code>）</strong>：每条 URL 使用 <strong><code>inferMediaKind</code></strong>。</li><li><strong><code>autoDetect === false</code></strong>：每条 URL 均按 <strong><code>displayType</code></strong>（<strong><code>image</code> | <code>video</code> | <code>file</code></strong>）渲染；<strong>调用方保证 URL 与类型一致</strong>，组件不做自动纠正。</li></ul><hr><h2 id="_4-urls-解析-6b" tabindex="-1">4. <code>urls</code> 解析（<strong>6B</strong>） <a class="header-anchor vp-link" href="#_4-urls-解析-6b" aria-label="Permalink to &quot;4. `urls` 解析（**6B**）&quot;">​</a></h2><ul><li><strong>唯一入参形态（首版）</strong>：<strong><code>urls: string</code></strong>，内容为 <strong>逗号分隔</strong>。</li><li>解析步骤：<strong><code>split(&#39;,&#39;)</code></strong> → 每项 <strong><code>trim</code></strong> → <strong>过滤空串</strong> → 得到 <strong><code>string[]</code></strong> 供内部使用。</li><li><strong>空列表</strong>：不渲染封面区（或仅 <strong><code>coverType=button</code></strong> 时渲染禁用态按钮——实现计划二选一，须在实现中写死并加单测 / E2E 之一）。</li></ul><hr><h2 id="_5-covertype-与封面表现" tabindex="-1">5. <code>coverType</code> 与封面表现 <a class="header-anchor vp-link" href="#_5-covertype-与封面表现" aria-label="Permalink to &quot;5. `coverType` 与封面表现&quot;">​</a></h2><h3 id="_5-1-none-直接展示" tabindex="-1">5.1 <code>none</code>（直接展示） <a class="header-anchor vp-link" href="#_5-1-none-直接展示" aria-label="Permalink to &quot;5.1 `none`（直接展示）&quot;">​</a></h3><ul><li><strong>image</strong>：每条 <strong><code>el-image</code></strong>；<strong><code>preview-src-list</code></strong> 为 <strong>全部图片 URL</strong>（保持 URL 原始顺序中的图片子序列顺序，与 <strong>第 6 节</strong> 一致）；<strong><code>initial-index</code></strong> 为当前图在「仅图片 URL 列表」中的下标。</li><li><strong>video</strong>：每条独立 <strong>封面容器</strong>（尺寸受 <strong><code>width</code> / <code>height</code></strong> 约束，见 <strong>第 8 节</strong>）；<strong>不</strong>将视频 URL 作为 <strong><code>poster</code></strong>（<strong>2B</strong>）；使用 <strong>统一占位</strong>（如中性底 + <strong>中央播放图标</strong>）。点击走 <strong>第 7 节</strong> 弹窗流程。</li><li><strong>file</strong>：<strong>文件图标 + 文件名</strong>（从 pathname 取 basename，无则显示兜底短文案如「文件」）。点击 <strong><code>window.open(url, &#39;_blank&#39;, &#39;noopener,noreferrer&#39;)</code></strong>（未被 <strong>第 9 节</strong> 钩子拦截时）。</li></ul><p><strong>混合类型</strong>：同一区域按条渲染 <strong>图块 / 视频块 / 文件块</strong>（可多行或多列布局以实现计划为准，须避免互相挤压不可点）。</p><h3 id="_5-2-button" tabindex="-1">5.2 <code>button</code> <a class="header-anchor vp-link" href="#_5-2-button" aria-label="Permalink to &quot;5.2 `button`&quot;">​</a></h3><ul><li><strong><code>el-button</code></strong> + 可选 <strong><code>el-badge</code></strong> 显示 <strong>解析后条数</strong>（条数为 <strong>第 4 节</strong> 解析结果长度）。</li><li>文案：<strong><code>previewText</code></strong> prop，默认 <strong><code>预览</code></strong>（不强制 i18n 词条文件，与现有 C7 风格协调即可）。</li><li><strong>点击后分支</strong>（与「验收：与 none 下单条同类操作效果一致」对齐）： <ol><li><strong>若至少存在一条 <code>image</code></strong>：触发 <strong>与 none 下点击图片等价的「大图预览」</strong>——<strong><code>preview-src-list</code> = 全部图片 URL</strong>（顺序同 <strong>第 6 节</strong>），<strong><code>initial-index = 0</code></strong>（即从第一张图进入预览器；用户可在预览器内切换其它图）。</li><li><strong>否则若至少存在一条 <code>video</code></strong>：打开 <strong>第 7 节</strong> 所述弹窗，<strong>初始播放索引 = 0</strong>（在 <strong>仅视频 URL 列表</strong> 中的下标）；若 <strong>视频条数 &gt; 1</strong>，弹窗内提供 <strong>上一条 / 下一条</strong> 切换当前 <strong><code>video.src</code></strong>（切换前 <strong>pause + <code>currentTime = 0</code></strong>）。</li><li><strong>否则（仅 <code>file</code>）</strong>：对 <strong>索引 0</strong> 的 URL 执行 <strong><code>window.open</code></strong>（<strong>不</strong>在首版一次打开多窗）。</li><li><strong>若解析后列表为空</strong>：no-op 或 <strong><code>console.warn</code></strong>（实现计划写死一种）。</li></ol></li></ul><blockquote><p><strong>说明</strong>：<strong>「图 + 视频 + 文件」同时存在</strong> 时，<strong><code>button</code> 单次点击</strong> 按 <strong>1 → 2 → 3</strong> 优先级执行（<strong>有图则只进入图片预览</strong>）。业务若需在混合集合下优先看视频，应拆数据或使用 <strong><code>coverType=none</code> / <code>file</code></strong>。</p></blockquote><h3 id="_5-3-file-5b" tabindex="-1">5.3 <code>file</code>（<strong>5B</strong>） <a class="header-anchor vp-link" href="#_5-3-file-5b" aria-label="Permalink to &quot;5.3 `file`（**5B**）&quot;">​</a></h3><ul><li>使用 <strong><code>el-table</code></strong> <strong>极简表</strong>（建议列：<strong>类型图标或扩展名</strong>、<strong>文件名</strong>；列数与宽度实现计划定）。</li><li><strong>行点击</strong>：对应该行索引 <strong><code>index</code></strong>，触发 <strong>与 <code>none</code> 下点击同索引条目相同</strong> 的预览或打开逻辑（图片进预览器且 <strong><code>initial-index</code></strong> 为该图在「仅图片列表」中的下标；视频进 <strong>第 7 节</strong> 弹窗单条播放；文件 <strong><code>window.open</code></strong>）。</li></ul><hr><h2 id="_6-图片列表顺序-实现约束" tabindex="-1">6. 图片列表顺序（实现约束） <a class="header-anchor vp-link" href="#_6-图片列表顺序-实现约束" aria-label="Permalink to &quot;6. 图片列表顺序（实现约束）&quot;">​</a></h2><p>内部维护 <strong><code>parsedUrls: string[]</code></strong>（顺序与 <strong><code>urls</code> 解析顺序一致</strong>）。<br><strong><code>preview-src-list</code></strong> 始终为 <strong><code>parsedUrls</code> 中类型为 <code>image</code> 的 URL 按出现顺序组成的数组</strong>；任意图片条目计算 <strong><code>initial-index</code></strong> 时，均为该 URL 在此数组中的下标。</p><hr><h2 id="_7-视频弹窗-3b-原始「关闭暂停」" tabindex="-1">7. 视频弹窗（<strong>3B</strong> + 原始「关闭暂停」） <a class="header-anchor vp-link" href="#_7-视频弹窗-3b-原始「关闭暂停」" aria-label="Permalink to &quot;7. 视频弹窗（**3B** + 原始「关闭暂停」）&quot;">​</a></h2><ul><li>使用 <strong><code>C7Dialog</code></strong>：<strong><code>footer=false</code></strong>，避免默认「取消/确定」占高。</li><li><strong>标题</strong>：<strong><code>videoDialogTitle</code></strong> prop，默认 <strong><code>视频预览</code></strong>。</li><li>内容：<strong><code>&lt;video controls autoplay :src=&quot;currentUrl&quot;&gt;</code></strong>。</li><li><strong>关闭</strong>（含遮罩、右上角关闭、<strong><code>v-model</code> 置 false<code>**）：**</code>video.pause()<code>**、**</code>video.currentTime = 0<code>**、**</code>emit(&#39;close&#39;)`</strong>。</li><li><strong>上一条 / 下一条</strong>（见 <strong>第 5.2 节</strong>）：切换前对当前 <strong><code>video</code> ref</strong> 执行 <strong>pause + 归零</strong> 再赋新 <strong><code>src</code></strong>。</li></ul><hr><h2 id="_8-尺寸与透传-对应原始需求-width-height" tabindex="-1">8. 尺寸与透传（对应原始需求 <code>width</code> / <code>height</code>） <a class="header-anchor vp-link" href="#_8-尺寸与透传-对应原始需求-width-height" aria-label="Permalink to &quot;8. 尺寸与透传（对应原始需求 `width` / `height`）&quot;">​</a></h2><ul><li><strong><code>width</code> / <code>height</code></strong>：类型 <strong><code>number</code></strong> 时视为 <strong>px</strong>，拼 <strong><code>${n}px</code></strong> 绑定到 <strong>封面容器</strong>（<code>none</code> 下单格；<code>video</code> 占位同）；<strong>不</strong>替代 <strong><code>el-image</code></strong> 的 <strong><code>fit</code></strong> 等。</li><li>首版可选 <strong><code>imageProps</code></strong> 对象透传到 <strong><code>el-image</code></strong>（实现计划：若成本低则做，否则仅 <strong><code>width/height</code></strong>）。</li></ul><hr><h2 id="_9-钩子与事件-4b" tabindex="-1">9. 钩子与事件（<strong>4B</strong>） <a class="header-anchor vp-link" href="#_9-钩子与事件-4b" aria-label="Permalink to &quot;9. 钩子与事件（**4B**）&quot;">​</a></h2><div class="vp-table"><table><thead><tr><th>项</th><th>约定</th></tr></thead><tbody><tr><td><strong><code>onPreview(url, index)</code></strong></td><td>返回值 <strong><code>boolean | Promise&lt;boolean&gt;</code></strong>；<strong><code>false</code> / <code>Promise&lt;false&gt;</code> / <code>Promise</code> reject</strong> → <strong>阻止</strong>后续预览或 <strong><code>window.open</code></strong>；<strong><code>true</code> / resolve 其它真值</strong> → 继续。未传钩子 → <strong>视为允许</strong>。</td></tr><tr><td><strong>调用顺序</strong></td><td><strong>先</strong> <strong><code>await</code> 归一化钩子结果</strong>；若允许，<strong>再</strong> <strong><code>emit(&#39;preview&#39;, url, index)</code></strong>，<strong>再</strong>执行具体 UI（大图 / 弹窗 / 新窗口）。</td></tr><tr><td><strong><code>preview</code></strong></td><td><strong><code>emit(&#39;preview&#39;, url: string, index: number)</code></strong>，在 <strong>通过钩子之后</strong>、<strong>打开预览器 / 弹窗 / 新窗口之前</strong>。</td></tr><tr><td><strong><code>close</code></strong></td><td><strong>视频弹窗</strong>从打开态变为关闭态时 <strong><code>emit(&#39;close&#39;)</code></strong> 一次（与原始需求一致）。</td></tr></tbody></table></div><hr><h2 id="_10-与-element-plus-的衔接-实现计划落点" tabindex="-1">10. 与 Element Plus 的衔接（实现计划落点） <a class="header-anchor vp-link" href="#_10-与-element-plus-的衔接-实现计划落点" aria-label="Permalink to &quot;10. 与 Element Plus 的衔接（实现计划落点）&quot;">​</a></h2><ul><li><strong>图片</strong>：优先 <strong><code>el-image</code> + <code>preview-src-list</code> + <code>initial-index</code></strong>；<strong><code>button</code></strong> 模式可用 <strong>隐藏 <strong><code>el-image</code></strong>（<code>opacity:0</code> + 固定 1px 或 <code>visibility</code> 策略）+ <strong><code>ref</code> 触发 <code>click()</code></strong> 打开预览</strong>（以 EP 版本实际 API 为准，若 API 变更则采用官方等价写法）。</li><li><strong>表格</strong>：<strong><code>el-table</code></strong> <strong><code>show-header</code></strong> 可按需关闭以减噪；<strong><code>row-style</code></strong> 指针手型提示可点。</li></ul><hr><h2 id="_11-验收与测试建议" tabindex="-1">11. 验收与测试建议 <a class="header-anchor vp-link" href="#_11-验收与测试建议" aria-label="Permalink to &quot;11. 验收与测试建议&quot;">​</a></h2><ul><li><strong>多图</strong>：<code>none</code> 与 <strong><code>button</code></strong> 均能进入带 <strong>完整图片列表</strong> 的预览，<strong><code>initial-index</code></strong> 符合 <strong>第 5～6 节</strong>。</li><li><strong>视频</strong>：弹窗内可播；关闭后 <strong>暂停且进度归零</strong>；<strong><code>close</code></strong> 已触发。</li><li><strong>文件</strong>：新窗口打开；<strong><code>noopener,noreferrer</code></strong>。</li><li><strong><code>onPreview</code> 返回 <code>false</code> 或 reject</strong>：不打开预览 / 不 <strong><code>window.open</code></strong>，且 <strong>不</strong> <strong><code>emit(&#39;preview&#39;)</code></strong>。</li><li><strong>单测</strong>：<strong><code>parseUrls</code></strong>（逗号、空格、空段）、<strong><code>inferMediaKind</code></strong>（query、大小写）。</li><li><strong>E2E</strong>：与其它 C7 页同模式增加 <strong><code>C7PreviewE2E</code></strong> 覆盖关键路径（实现计划列用例表）。</li></ul><hr><h2 id="_12-后续流程" tabindex="-1">12. 后续流程 <a class="header-anchor vp-link" href="#_12-后续流程" aria-label="Permalink to &quot;12. 后续流程&quot;">​</a></h2><ul><li>实现前：由 <strong><code>writing-plans</code></strong> 产出分步实现计划（含 <strong><code>packages/index.js</code> 注册</strong>、<strong><code>C7Dialog</code> 联调</strong>、<strong>EP 预览触发</strong>细节）。</li><li>本文档经用户审阅无修改后，再进入编码阶段。</li></ul>',47)])])}const u=e(s,[["render",g]]);export{p as __pageData,u as default};
